def load(s):
 d=pd.read_csv('../persistent/stock_data/'+s+'.csv',parse_dates=['date']).drop_duplicates('date').set_index('date'); return d.close.rename(s)
p=pd.concat([load(s) for s in U],axis=1).sort_index(); r=p.pct_change(); fac=pd.DataFrame(index=p.index,columns=U,dtype=float)
# 60d rolling residual return versus SPX and XAU; signal is trailing 10-session sum of residuals, fully lagged
for i,dt in enumerate(p.index):
 if i<70: continue
 w=r.iloc[i-60:i][['SPX','XAU']]
 for s in U:
  z=pd.concat([r[s].iloc[i-60:i],w],axis=1).dropna()
  if len(z)<40: continue
  X=np.column_stack([np.ones(len(z)),z[['SPX','XAU']].values]); b=np.linalg.lstsq(X,z[s].values,rcond=None)[0]
  resid=r[s].iloc[i-10:i] - b[1]*r['SPX'].iloc[i-10:i] - b[2]*r['XAU'].iloc[i-10:i] - b[0]
  if resid.notna().sum()>=8: fac.loc[dt,s]=resid.sum()
# metrics
def calc(h):
 fw=p.pct_change(h).shift(-h); vals=[]; ns=[]; dates=[]
 for dt in fac.index:
  z=pd.DataFrame({'f':fac.loc[dt],'y':fw.loc[dt]}).dropna()
  if len(z)>=8 and z.f.nunique()>1 and z.y.nunique()>1:
   vals.append(spearmanr(z.f,z.y).statistic); ns.append(len(z)); dates.append(dt)
 a=np.array(vals); print('h',h,'dates',len(a),'avgN',round(np.mean(ns),2),'IC',round(a.mean(),6),'ICIR',round(a.mean()/a.std(ddof=1),6),'hit',round((a>0).mean(),4))
 for lo,hi in [(2020,2022),(2023,2024),(2025,2026)]:
  q=a[[lo<=d.year<=hi for d in dates]]; print('regime',lo,hi,'n',len(q),'IC',round(q.mean(),6) if len(q) else None,'ICIR',round(q.mean()/q.std(ddof=1),6) if len(q)>1 else None)
for h in [1,5,10]: calc(h)
rank=fac.rank(axis=1,pct=True); print('coverage',round(fac.notna().mean().mean(),4),'turnover',round(rank.diff().abs().mean(axis=1).mean(),4),'period',p.index.min().date(),p.index.max().date())
# correlations with common signals pooled
rows=[]
for s in U:
 for dt in fac.index:
  vals=[fac.loc[dt,s],-r[s].rolling(5).sum().loc[dt],r[s].rolling(20).sum().loc[dt]/r[s].rolling(20).std().loc[dt]]
  if all(np.isfinite(vals)): rows.append(vals)
c=np.array(rows); print('pooled_corr_reversal_mom',round(spearmanr(c[:,0],c[:,1]).statistic,4),round(spearmanr(c[:,0],c[:,2]).statistic,4))
# artifact for audit
out=fac.stack().rename('signal').reset_index(); out.columns=['date','symbol','signal']; out.to_csv('scripts/miner_3_20261008_residual_momentum_signal.csv',index=False)

