import numpy as np, pandas as pd, os
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
D={}
for s in U:
    f='../persistent/index_data/'+s+'.csv'
    if os.path.exists(f):
        x=pd.read_csv(f,parse_dates=['date']).sort_values('date').drop_duplicates('date').set_index('date')['close'].astype(float)
        D[s]=x
p=pd.DataFrame(D).sort_index().ffill(); ret=p.pct_change()
mom60=p/p.shift(60)-1; vol60=ret.rolling(60).std()*np.sqrt(252); mom20=p/p.shift(20)-1
sig=(mom60/vol60)*(1+0.5*np.sign(mom60)*np.sign(mom20))
for h in [5,10,20]:
 vals=[]; dates=[]; cs=[]; fwd=p.shift(-h)/p-1
 for dt in sig.index:
