# Adaptive residual reversal: blend a fast 3d shock with a slower 10d residual
# move, with stronger fast reversal only when recent cross-asset dispersion is high.
def factor(i):
 rvol=res.iloc[i-19:i+1].std(); z3=-res.iloc[i-2:i+1].sum()/(rvol+1e-12)
 z10=-res.iloc[i-9:i+1].sum()/(rvol*np.sqrt(10/3)+1e-12)
 disp20=R.iloc[i-19:i+1].std(axis=1).mean(); disp60=R.iloc[i-59:i+1].std(axis=1).mean()
 state=np.clip(disp20/(disp60+1e-12),0.6,1.8)
 w=np.clip((state-0.6)/1.2,0,1)
 return (0.25+0.5*w)*z3+(0.75-0.5*w)*z10

def run(h):
 rows=[]; sig=[]
 for i in range(120,len(P)-h):
  f=factor(i); y=P.iloc[i+h]/P.iloc[i]-1
  z=pd.DataFrame({'f':f,'y':y}).replace([np.inf,-np.inf],np.nan).dropna()
