import glob,pandas as pd, numpy as np, os
f='scripts/miner_3_20320805_vix_beta_stress_reversal_signal.csv'; a=pd.read_csv(f); a['k']=a.date+'|'+a.symbol; x=a.set_index('k').signal
mx=0; who=''
for g in glob.glob('scripts/*_signal.csv'):
 if g==f: continue
 try:
  b=pd.read_csv(g); b['k']=b.date+'|'+b.symbol; z=pd.concat([x,b.set_index('k').signal],axis=1).dropna()
  if len(z)>30:
   c=abs(z.iloc[:,0].corr(z.iloc[:,1]));
   if c>mx: mx=c; who=os.path.basename(g)
 except: pass
print(mx,who)
PY

